// Gelen verinin 'text' alanını al
const geminiText = $input.item.json.text;

if (!geminiText) {
  throw new Error("Gemini'den metin gelmedi veya 'text' alanı boş.");
}

let startTime;
let endTime;

// Helper function to convert HH:MM:SS.mmm to seconds
function timeToSeconds(timeStr) {
  if (!timeStr || typeof timeStr !== 'string') return NaN;
  const parts = timeStr.split(':');
  if (parts.length !== 3) return NaN;
  const secondsAndMillis = parts[2].split('.');
  if (secondsAndMillis.length !== 2) return NaN;

  const hours = parseInt(parts[0], 10);
  const minutes = parseInt(parts[1], 10);
  const seconds = parseInt(secondsAndMillis[0], 10);
  const milliseconds = parseInt(secondsAndMillis[1], 10);

  if (isNaN(hours) || isNaN(minutes) || isNaN(seconds) || isNaN(milliseconds) ||
      hours < 0 || minutes < 0 || minutes >= 60 || seconds < 0 || seconds >= 60 || milliseconds < 0 || milliseconds >= 1000) {
    return NaN; // Invalid time components
  }
  return (hours * 3600) + (minutes * 60) + seconds + (milliseconds / 1000);
}

// Regex to find HH:MM:SS,mmm or HH:MM:SS.mmm format
const timeRegexStr = "(\\d{2}:\\d{2}:\\d{2}[.,]\\d{3})"; // String for new RegExp
const timeRegexGlobal = new RegExp(timeRegexStr, 'g'); // For multiple matches if needed

// Try to extract using START: and END:
const startMatch = geminiText.match(new RegExp("START:\\s*" + timeRegexStr));
const endMatch = geminiText.match(new RegExp("END:\\s*" + timeRegexStr));

if (startMatch && startMatch[1] && endMatch && endMatch[1]) {
  console.log("İdeal format (START:/END:) regex ile tespit edildi.");
  startTime = startMatch[1].replace(',', '.');
  endTime = endMatch[1].replace(',', '.');
} else {
  console.log("İdeal format (START:/END:) regex ile bulunamadı, alternatif '-->' formatı deneniyor.");
  if (geminiText.includes('-->')) {
    const parts = geminiText.split('-->');
    if (parts.length === 2) {
      const startPartTimes = parts[0].match(timeRegexGlobal);
      const endPartTimes = parts[1].match(timeRegexGlobal);
      if (startPartTimes && startPartTimes.length > 0) {
        startTime = startPartTimes[startPartTimes.length - 1].replace(',', '.');
      }
      if (endPartTimes && endPartTimes.length > 0) {
        endTime = endPartTimes[0].replace(',', '.');
      }
      if (startTime && endTime) {
        console.log("Alternatif '-->' formatı regex ile tespit edildi (startTime: " + startTime + ", endTime: " + endTime + ").");
      } else {
        console.log("Alternatif '-->' formatında zamanlar regex ile tam olarak bulunamadı.");
      }
    } else {
      console.log("'-->' formatı beklenildiği gibi ikiye ayrılamadı.");
    }
  }
}

if (!startTime || !endTime) {
   throw new Error(`Zaman damgaları ayrıştırılamadı. Gelen Metin: "${geminiText}", Çıkarılan startTime: ${startTime}, Çıkarılan endTime: ${endTime}`);
}

const timePattern = /^\\d{2}:\\d{2}:\\d{2}\\.\\d{3}$/;
if (!timePattern.test(startTime) || !timePattern.test(endTime)) {
  throw new Error(`Ayrıştırılan zaman damgaları beklenen formatta (HH:MM:SS.mmm) değil. startTime=${startTime}, endTime=${endTime}`);
}

// Duration Check
const startSeconds = timeToSeconds(startTime);
const endSeconds = timeToSeconds(endTime);

if (isNaN(startSeconds) || isNaN(endSeconds)) {
  throw new Error(`Geçersiz zaman formatı nedeniyle süre hesaplanamadı. startTime: ${startTime}, endTime: ${endTime}`);
}

if (startSeconds >= endSeconds) {
  throw new Error(`Başlangıç zamanı (${startTime}) bitiş zamanından (${endTime}) sonra veya eşit olamaz.`);
}

const duration = endSeconds - startSeconds;
console.log(`Hesaplanan süre: ${duration.toFixed(3)} saniye.`);

const minDuration = 15;
const maxDuration = 30;

if (duration < minDuration || duration > maxDuration) {
  throw new Error(`Çıkarılan klip süresi (${duration.toFixed(3)}s) beklenen ${minDuration}-${maxDuration} saniye aralığının dışında. Gemini'nin verdiği zamanlar: startTime: ${startTime}, endTime: ${endTime}. Lütfen Gemini prompt'unu veya modelini kontrol edin.`);
}

// Sonuçları bir sonraki noda gönder
return {
  startTime: startTime,
  endTime: endTime,
  duration: duration.toFixed(3) // Optional: pass duration along
};
